salidas = []

for indice, elemento in enumerate(_items):
    datos = elemento.get("json", {})

    # 1. Recuperar los datos del formulario
    zona = datos.get("Zona de trabajo")
    supervisor = datos.get("Identificador del supervisor")

    # 2. Validar la zona y el supervisor
    if zona != "zona_operativa":
        raise ValueError("Zona de trabajo no válida.")

    if not str(supervisor or "").strip():
        raise ValueError("Falta el identificador del supervisor.")

    # 3. Comprobar que se recibió una sola imagen
    binarios = elemento.get("binary") or {}

    if len(binarios) != 1:
        raise ValueError("Debe recibirse exactamente una imagen.")

    clave_imagen = next(iter(binarios))
    imagen = binarios[clave_imagen]

    # 4. Validar el formato de imagen
    formatos_permitidos = [
        "image/jpeg",
        "image/png",
        "image/webp"
    ]

    if imagen.get("mimeType") not in formatos_permitidos:
        raise ValueError("Formato de imagen no permitido.")

    # 5. Revisar el tamaño máximo de 5 MB
    archivo_formulario = datos.get("Fotografía de la zona")
    tamano = None

    if isinstance(archivo_formulario, list) and archivo_formulario:
        primero = archivo_formulario[0]

        if isinstance(primero, dict):
            tamano = primero.get("size")

    if isinstance(tamano, (int, float)) and tamano > 5 * 1024 * 1024:
        raise ValueError("La imagen supera los 5 MB.")

    # 6. Preparar la salida para YOLO
    salidas.append({
        "json": {
            "zona_id": zona,
            "supervisor": str(supervisor).strip(),
            "imagen_nombre": imagen.get("fileName"),
            "imagen_tipo": imagen.get("mimeType"),
            "imagen_bytes": tamano,
            "fecha_envio": datos.get("submittedAt"),
            "estado": "entrada_validada"
        },

        # Mantener la imagen para el nodo HTTP
        "binary": {
            "imagen": imagen
        },

        "pairedItem": {
            "item": indice
        }
    })

return salidas

# Validar el informe de Gemini y preparar la salida final

salidas = []

for indice, elemento in enumerate(_items):

    datos = elemento.get("json", {})
    informe = datos.get("informe")
    anterior = datos.get("anterior")

    # 1. Comprobar que llegaron los datos necesarios
    if not isinstance(informe, dict):
        raise ValueError("Gemini no devolvió un objeto JSON válido.")

    if not isinstance(anterior, dict):
        raise ValueError("No se recuperaron los datos de la inspección.")

    # 2. Validar los cuatro campos obligatorios de Gemini
    campos = [
        "diagnostico",
        "recomendacion",
        "prioridad",
        "justificacion"
    ]

    for campo in campos:
        valor = informe.get(campo)

        if not isinstance(valor, str) or not valor.strip():
            raise ValueError(
                "Campo obligatorio inválido: " + campo
            )

        informe[campo] = valor.strip()

    # 3. Comprobar la prioridad
    if informe["prioridad"] not in ["alta", "media", "baja"]:
        raise ValueError("Prioridad inválida.")

    # 4. Recuperar los resultados originales de YOLO
    yolo = anterior.get("resultado_yolo")

    if not isinstance(yolo, dict):
        raise ValueError("Faltan los resultados originales de YOLO.")

    resumen = yolo.get("resumen") or {}

    if "requieren_revision" not in resumen:
        raise ValueError(
            "Falta el resumen de trabajadores que requieren revisión."
        )

    # 5. Consolidar la inspección para Gmail, Telegram y Sheets
    salidas.append({
        "json": {
            "fecha_inspeccion": anterior.get("fecha_envio"),
            "fecha_procesamiento": datos.get("fecha_procesamiento"),

            "supervisor": anterior.get("supervisor"),
            "imagen_nombre": anterior.get("imagen_nombre"),

            "zona_id": yolo.get("zona_id"),
            "zona": yolo.get("zona"),
            "reglas_validadas": yolo.get("reglas_validadas"),

            "modelo_vision": yolo.get("modelo"),
            "modelo_llm": "gemini-3.1-flash-lite",

            "cantidad_trabajadores": yolo.get(
                "cantidad_trabajadores"
            ),
            "trabajadores": yolo.get("trabajadores"),
            "trabajadores_revision": resumen["requieren_revision"],

            "informe_llm": {
                "diagnostico": informe["diagnostico"],
                "recomendacion": informe["recomendacion"],
                "prioridad": informe["prioridad"],
                "justificacion": informe["justificacion"]
            },

            "revision_humana": {
                "requerida": True,
                "estado": "pendiente"
            },

            "advertencia": yolo.get("advertencia"),
            "estado_flujo": "informe_generado"
        },

        "pairedItem": {
            "item": indice
        }
    })

return salidas

