# Convertir datos de Python a texto JSON sin bibliotecas externas
def convertir_json(valor):
    if valor is None:
        return "null"

    if isinstance(valor, bool):
        return "true" if valor else "false"

    if isinstance(valor, str):
        caracteres = []
        for caracter in valor:
            if caracter == '"':
                caracteres.append('\\"')
            elif caracter == "\\":
                caracteres.append("\\\\")
            elif ord(caracter) < 32:
                caracteres.append("\\u%04x" % ord(caracter))
            else:
                caracteres.append(caracter)
        return '"' + "".join(caracteres) + '"'

    if isinstance(valor, (int, float)):
        return str(valor)

    if isinstance(valor, list):
        return "[" + ",".join(
            convertir_json(v) for v in valor
        ) + "]"

    if isinstance(valor, dict):
        return "{" + ",".join(
            convertir_json(str(k)) + ":" + convertir_json(v)
            for k, v in valor.items()
        ) + "}"

    return convertir_json(str(valor))


for indice, elemento in enumerate(_items):

    datos = elemento.get("json", {})

    # 1. Recuperar información del formulario
    supervisor = datos.get("supervisor")
    imagen_nombre = datos.get("imagen_nombre")
    fecha_envio = datos.get("fecha_envio")

    if not supervisor or not imagen_nombre or not fecha_envio:
        raise ValueError("Faltan datos del formulario.")

    # 2. Separar los resultados originales de YOLO
    yolo = {
        clave: valor
        for clave, valor in datos.items()
        if clave not in [
            "supervisor",
            "imagen_nombre",
            "fecha_envio"
        ]
    }

    # 3. Verificar que YOLO entregó resultados válidos
    if (
        not isinstance(yolo.get("trabajadores"), list)
        or not isinstance(yolo.get("epp_requeridos"), list)
    ):
        raise ValueError("La respuesta de YOLO está incompleta.")

    # 4. Resumir los EPP de cada trabajador
    trabajadores = []

    for t in yolo["trabajadores"]:
        trabajadores.append({
            "id": t.get("persona_id"),
            "epp_confirmados": list(
                (t.get("epp_detectados") or {}).keys()
            ),
            "epp_no_confirmados": t.get(
                "epp_no_confirmados"
            ) or []
        })

    # 5. Preparar los datos que recibirá Gemini
    entrada_llm = {
        "zona": yolo.get("zona"),
        "reglas_academicas": not yolo.get("reglas_validadas"),
        "epp_requeridos": yolo["epp_requeridos"],
        "trabajadores_detectados": yolo.get(
            "cantidad_trabajadores"
        ),
        "trabajadores": trabajadores
    }

    # 6. Instrucciones originales para Gemini
    instrucciones = """
Eres un asistente de prevención de riesgos.

Interpreta exclusivamente los resultados proporcionados.

Reglas:
- No afirmes que un EPP está ausente si no fue detectado.
- No declares incumplimientos confirmados.
- Las reglas de zona son académicas.
- No inventes leyes ni hechos observados.
- El nombre de la zona no demuestra que haya maquinaria visible.
- Recomienda revisión humana ante incertidumbre.
- La prioridad refleja urgencia de revisión, no infracción.
- Máximo 70 palabras en total.

Responde SOLO con un objeto JSON válido que contenga:
"diagnostico": texto breve,
"recomendacion": acción concreta,
"prioridad": "alta", "media" o "baja",
"justificacion": razón breve.
"""

    # 7. Unir instrucciones y datos
    prompt_gemini = (
        instrucciones
        + "\nDATOS:\n"
        + convertir_json(entrada_llm)
    )

    # 8. Conservar los datos para los siguientes nodos
    salidas.append({
        "json": {
            "supervisor": supervisor,
            "imagen_nombre": imagen_nombre,
            "fecha_envio": fecha_envio,
            "resultado_yolo": yolo,
            "entrada_llm": entrada_llm,
            "prompt_gemini": prompt_gemini,
            "estado_flujo": "pendiente_gemini"
        },
        "pairedItem": {
            "item": indice
        }
    })

return salidas

